fn solve(n: i8) -> Vec<i8> {
    // Number of complete 7-day weeks
    let weeks = n / 7;
    // Remainder days beyond the complete weeks (0..=6)
    let r = n % 7;
    // Base days off from the complete weeks
    let base_off = weeks * 2;
    // Minimum extra days off in the remainder: max(0, r - 5)
    let min_extra = if r > 5 { r - 5 } else { 0 };
    // Maximum extra days off in the remainder: min(2, r)
    let max_extra = if r < 2 { r } else { 2 };
    vec![base_off + min_extra, base_off + max_extra]
}

